const envelope = ($json.body && typeof $json.body === 'object') ? $json.body : $json;
const data = (envelope.data && typeof envelope.data === 'object') ? envelope.data : envelope;

function readPath(obj, path) {
  return path.split('.').reduce((acc, key) => {
    if (acc && typeof acc === 'object' && key in acc) return acc[key];
    return undefined;
  }, obj);
}

function pick(obj, paths, fallback = '') {
  for (const path of paths) {
    const value = readPath(obj, path);
    if (value !== undefined && value !== null && String(value).trim() !== '') {
      return String(value).trim();
    }
  }
  return fallback;
}

function pickBool(obj, paths, fallback = false) {
  for (const path of paths) {
    const value = readPath(obj, path);
    if (typeof value === 'boolean') return value;
    if (value === 1 || value === '1') return true;
    if (typeof value === 'string') {
      const normalized = value.trim().toLowerCase();
      if (['true', 'yes', 'sim', 'on'].includes(normalized)) return true;
      if (['false', 'no', 'nao', 'off'].includes(normalized)) return false;
    }
  }
  return fallback;
}

function normalizePhone(value) {
  const base = String(value || '').replace(/@.+$/g, '').replace(/\D+/g, '');
  if (!base) return '';
  return base.startsWith('55') ? base : `55${base}`;
}

function normalizeSqlPhone(fieldName) {
  return `REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(${fieldName}, ''), '(', ''), ')', ''), '-', ''), ' ', ''), '+', '')`;
}

function detectStructuredMessageType(payload) {
  const checks = [
    ['message.audioMessage', 'audio'],
    ['message.ptvMessage', 'video'],
    ['message.videoMessage', 'video'],
    ['message.imageMessage.caption', 'imagem'],
    ['message.imageMessage', 'imagem'],
    ['message.documentMessage.caption', 'arquivo'],
    ['message.documentMessage', 'arquivo'],
    ['message.documentWithCaptionMessage.message.documentMessage', 'arquivo'],
    ['message.stickerMessage', 'imagem'],
    ['message.contactMessage', 'contato'],
    ['message.contactsArrayMessage', 'contato'],
    ['message.locationMessage', 'localizacao'],
    ['message.liveLocationMessage', 'localizacao'],
    ['message.reactionMessage', 'reacao']
  ];

  for (const [path, type] of checks) {
    const value = readPath(payload, path);
    if (value && typeof value === 'object') {
      return type;
    }
    if (typeof value === 'string' && value.trim() !== '') {
      return type;
    }
  }

  return 'texto';
}

const companyName = 'Jovem Tech';
const erpWebhookUrl = 'https://sistema.jovemtech.eco.br/webhooks/whatsapp';
const erpWebhookToken = 'COLE_O_TOKEN_WEBHOOK_ERP';
const erpOrigin = 'https://sistema.jovemtech.eco.br';

const evolutionBaseUrl = 'https://evo.jovemtech.eco.br';
const evolutionApiKey = 'COLE_A_API_KEY_DA_EVOLUTION';
const evolutionInstance = 'chatwoot';

const rawEventName = pick(envelope, ['event', 'type', 'webhookEvent', 'trigger'], '');
const eventName = rawEventName.toUpperCase();
const normalizedEventName = eventName.replace(/\./g, '_');
const instanceName = pick(envelope, ['instance', 'instanceName', 'sender'], evolutionInstance);
const remoteJid = pick(data, [
  'key.remoteJid',
  'remoteJid',
  'jid',
  'chatId',
  'from',
  'sender',
  'phone',
  'number'
], '');
const participant = pick(data, ['participant', 'key.participant'], '');
const pushName = pick(data, ['pushName', 'contact.pushName', 'contact.name'], '');
const fromMe = pickBool(data, ['key.fromMe', 'fromMe'], false);
const isGroup = /@g\.us$/i.test(remoteJid);
const phone = normalizePhone(remoteJid || pick(data, ['from', 'sender', 'phone', 'number'], ''));
const phoneNoCountry = phone.replace(/^55/, '');
const memorySessionKey = remoteJid || phone;
const messageKeyId = pick(data, ['key.id', 'id'], '');
const deliveryStatus = pick(data, ['status'], '');

const text = pick(data, [
  'message.conversation',
  'message.extendedTextMessage.text',
  'message.imageMessage.caption',
  'message.videoMessage.caption',
  'message.documentMessage.caption',
  'message.documentWithCaptionMessage.message.documentMessage.caption',
  'message.buttonsResponseMessage.selectedDisplayText',
  'message.listResponseMessage.title',
  'message.listResponseMessage.singleSelectReply.selectedRowId',
  'message.templateButtonReplyMessage.selectedDisplayText',
  'body',
  'text',
  'message'
], '');

const normalizedText = text
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .toLowerCase()
  .trim();

const messageType = detectStructuredMessageType(data);
const hasMedia = messageType !== 'texto';
const hasMessageContent = text !== '' || hasMedia;
const isInboundEvent = normalizedEventName === 'MESSAGES_UPSERT';
const isManualTestPayload = normalizedEventName === '' && !fromMe && !isGroup && phone !== '' && text !== '';
const shouldProcess = (isInboundEvent || isManualTestPayload) && !fromMe && !isGroup && phone !== '' && hasMessageContent;
const shouldReply = shouldProcess;

const phoneValuesSql = [phone, phoneNoCountry]
  .filter((value, index, array) => value && array.indexOf(value) === index)
  .map((value) => `'${value.replace(/'/g, "''")}'`)
  .join(', ');

const phoneWhere = [
  normalizeSqlPhone('c.telefone1'),
  normalizeSqlPhone('c.telefone2'),
  normalizeSqlPhone('c.telefone_contato')
].map((expr) => `${expr} IN (${phoneValuesSql || "''"})`).join(' OR ');

const historicoPhoneWhere = [
  `${normalizeSqlPhone('c.telefone')} IN (${phoneValuesSql || "''"})`,
  `${normalizeSqlPhone('m.telefone')} IN (${phoneValuesSql || "''"})`
].join(' OR ');

const clienteLookupSql = `
SELECT *
FROM (
  SELECT
    1 AS cliente_encontrado,
    c.id,
    c.nome_razao,
    c.email,
    c.telefone1,
    c.telefone2,
    c.nome_contato,
    c.telefone_contato,
    c.cidade,
    c.uf,
    c.observacoes
  FROM clientes c
  WHERE ${phoneWhere}
  ORDER BY c.id DESC
  LIMIT 1
) cliente
UNION ALL
SELECT
  0 AS cliente_encontrado,
  NULL AS id,
  NULL AS nome_razao,
  NULL AS email,
  NULL AS telefone1,
  NULL AS telefone2,
  NULL AS nome_contato,
  NULL AS telefone_contato,
  NULL AS cidade,
  NULL AS uf,
  NULL AS observacoes
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1
  FROM clientes c
  WHERE ${phoneWhere}
  LIMIT 1
)
LIMIT 1;
`.trim();

const historicoLookupSql = `
SELECT *
FROM (
  SELECT
    m.id,
    m.created_at,
    m.direcao,
    m.tipo_mensagem,
    m.tipo_conteudo,
    m.mensagem,
    COALESCE(m.enviada_por_bot, 0) AS enviada_por_bot,
    CASE
      WHEN m.direcao = 'inbound' THEN 'cliente'
      WHEN COALESCE(m.enviada_por_bot, 0) = 1 THEN 'bot'
      WHEN m.tipo_mensagem = 'outbound_externo' OR m.tipo_mensagem LIKE '%externo%' THEN 'humano_app'
      ELSE 'humano_erp'
    END AS origem_resumida
  FROM mensagens_whatsapp m
  LEFT JOIN conversas_whatsapp c ON c.id = m.conversa_id
  WHERE ${historicoPhoneWhere}
  ORDER BY m.id DESC
  LIMIT 8
) historico
UNION ALL
SELECT
  NULL AS id,
  NULL AS created_at,
  NULL AS direcao,
  NULL AS tipo_mensagem,
  NULL AS tipo_conteudo,
  NULL AS mensagem,
  0 AS enviada_por_bot,
  NULL AS origem_resumida
FROM DUAL
WHERE NOT EXISTS (
  SELECT 1
  FROM mensagens_whatsapp m
  LEFT JOIN conversas_whatsapp c ON c.id = m.conversa_id
  WHERE ${historicoPhoneWhere}
  LIMIT 1
);
`.trim();

const erpPayload = {
  provider: 'evolution',
  source: 'evolution',
  event: rawEventName || eventName,
  instance: instanceName,
  push_name: pushName,
  participant,
  from_me: fromMe,
  has_media: hasMedia,
  normalized_phone: phone,
  normalized_text: text,
  detected_type: messageType,
  message_key_id: messageKeyId,
  delivery_status: deliveryStatus,
  n8n_workflow: 'evolution-whatsapp-atendimento-ia-memoria',
  n8n_received_at: new Date().toISOString(),
  ...envelope
};

return {
  ...$json,
  source: envelope,
  data,
  eventName,
  normalizedEventName,
  instanceName,
  companyName,
  normalizedPhone: phone,
  phoneNoCountry,
  remoteJid,
  memorySessionKey,
  messageKeyId,
  deliveryStatus,
  pushName,
  participant,
  receivedText: text,
  normalizedText,
  messageType,
  hasMedia,
  fromMe,
  isGroup,
  shouldProcess,
  shouldReply,
  erpWebhookUrl,
  erpWebhookToken,
  erpOrigin,
  evolutionBaseUrl,
  evolutionApiKey,
  evolutionInstance,
  clienteLookupSql,
  historicoLookupSql,
  erpPayload
};

const base = $('Normalizar Evolution e Credenciais').first().json;
const cliente = $('Buscar Cliente ERP').first().json || {};
const historicoRows = $('Buscar Historico Conversa ERP').all().map((item) => item.json || {});
const osRows = $('Buscar OS ERP').all().map((item) => item.json || {});
const clienteEncontrado = Number(cliente.cliente_encontrado || 0) === 1 && !!cliente.id;

function firstName(value) {
  return String(value || '').trim().split(/\s+/).filter(Boolean)[0] || '';
}

const profileFirstName = firstName(base.pushName);
const cadastroFirstName = firstName(cliente.nome_razao);
const nameConflict = profileFirstName !== '' && cadastroFirstName !== '' && profileFirstName.toLowerCase() !== cadastroFirstName.toLowerCase();
const preferredGreetingName = nameConflict ? (profileFirstName || cadastroFirstName) : (cadastroFirstName || profileFirstName);

const clienteResumo = clienteEncontrado
  ? [
      `ID: ${cliente.id}`,
      `Nome do cadastro ERP: ${cliente.nome_razao || '-'}`,
      `Email: ${cliente.email || '-'}`,
      `Telefone1: ${cliente.telefone1 || '-'}`,
      `Telefone2: ${cliente.telefone2 || '-'}`,
      `Contato: ${cliente.nome_contato || '-'}`,
      `Telefone do contato: ${cliente.telefone_contato || '-'}`,
      `Cidade/UF: ${(cliente.cidade || '-') + '/' + (cliente.uf || '-')}`,
      `Observacoes: ${cliente.observacoes || '-'}`
    ].join('\n')
  : 'Cliente nao localizado por telefone na tabela clientes.';

const historicoUtil = historicoRows
  .filter((row) => row && row.id && String(row.mensagem || '').trim() !== '')
  .sort((a, b) => Number(a.id) - Number(b.id))
  .slice(-8);

const historicoFormatado = historicoUtil.length > 0
  ? historicoUtil.map((row) => {
      const momento = String(row.created_at || '').replace('T', ' ').slice(0, 16) || '-';
      const origem = String(row.origem_resumida || row.direcao || 'desconhecido');
      const texto = String(row.mensagem || '').replace(/\s+/g, ' ').trim().slice(0, 280);
      return `${momento} | ${origem}: ${texto}`;
    }).join('\n')
  : 'Sem historico recente da conversa no ERP.';

const osUtil = osRows
  .filter((row) => row && row.id)
  .sort((a, b) => String(b.data_abertura || '').localeCompare(String(a.data_abertura || '')))
  .slice(0, 5);

const osResumo = osUtil.length > 0
  ? osUtil.map((row) => {
      const numero = row.numero_os || row.numero_os_legado || row.id;
      const equipamento = [row.numero_serie ? `serie:${row.numero_serie}` : '', row.imei ? `imei:${row.imei}` : '', row.cor ? `cor:${row.cor}` : ''].filter(Boolean).join(' | ');
      return [
        `OS ${numero}`,
        `status:${row.status || '-'}`,
        `fluxo:${row.estado_fluxo || '-'}`,
        `abertura:${String(row.data_abertura || '').replace('T', ' ').slice(0, 16) || '-'}`,
        `previsao:${row.data_previsao || '-'}`,
        `valor_final:${row.valor_final ?? '-'}`,
        `valor_total:${row.valor_total ?? '-'}`,
        `garantia:${row.garantia_dias ?? '-'} dias`,
        equipamento || 'equipamento: -',
        `relato:${String(row.relato_cliente || '-').replace(/\s+/g, ' ').trim().slice(0, 180)}`,
        `diagnostico:${String(row.diagnostico_tecnico || '-').replace(/\s+/g, ' ').trim().slice(0, 180)}`
      ].join(' | ');
    }).join('\n')
  : 'Nenhuma ordem de servico localizada para este cliente.';

const systemMessage = [
  `Voce e a atendente virtual da ${base.companyName}.`,
  'Fale como uma pessoa real no WhatsApp: natural, calorosa, objetiva e profissional.',
  'Use memoria e contexto para continuar a conversa de onde ela parou.',
  'Nao trate cada mensagem como um primeiro contato quando houver historico recente.',
  'Nao repita perguntas ja respondidas no historico ou no cadastro do ERP.',
  'Nao invente dados de OS, orcamento, valores, prazos, laudos ou qualquer informacao operacional que nao esteja no contexto.',
  'Se a pergunta do cliente for sobre conserto, aparelho, andamento, status, valor ou previsao, use primeiro o resumo de OS abaixo antes de responder.',
  'Se nao houver OS no contexto, diga isso com clareza e siga o atendimento sem inventar resultados.',
  'Se a pessoa mandar respostas curtas como ok, sim, nao, testei, deu certo ou ainda nao, interprete isso com base no historico recente.',
  'Evite respostas roboticas ou genericas demais.',
  'Quando a conversa ja estiver em andamento, nao repita saudacao completa; va direto ao ponto ou use uma abertura curta.',
  'Se houver divergencia entre o nome do perfil do WhatsApp e o nome do cadastro do ERP, nao trate nenhum dos dois como certeza absoluta; prefira linguagem neutra ou o primeiro nome mais seguro, sem insistir em nome errado.',
  'Faca no maximo uma pergunta objetiva por vez.',
  'A resposta deve ser curta, pronta para envio por WhatsApp, sem markdown.'
].join(' ');

const agentInput = [
  `Evento Evolution: ${base.normalizedEventName || base.eventName || '-'}`,
  `Telefone normalizado: ${base.normalizedPhone || '-'}`,
  `Nome de perfil WhatsApp: ${base.pushName || '-'}`,
  `Primeiro nome sugerido para saudacao: ${preferredGreetingName || '-'}`,
  `Existe divergencia entre nome do perfil e nome do cadastro: ${nameConflict ? 'sim' : 'nao'}`,
  `Cliente encontrado: ${clienteEncontrado ? 'sim' : 'nao'}`,
  `Tipo da mensagem: ${base.messageType || 'texto'}`,
  `Mensagem mais recente do cliente: ${base.receivedText || '(sem texto)'}`,
  'Contexto do cliente:',
  clienteResumo,
  'Historico recente da conversa no ERP:',
  historicoFormatado,
  'Ordens de servico recentes no ERP:',
  osResumo,
  'Responda agora ao cliente, considerando memoria e continuidade real da conversa.'
].join('\n\n');

return [{
  json: {
    ...base,
    clienteEncontrado,
    cliente,
    clienteResumo,
    historicoFormatado,
    historicoCount: historicoUtil.length,
    osResumo,
    osCount: osUtil.length,
    nameConflict,
    preferredGreetingName,
    openaiSystemMessage: systemMessage,
    agentInput
  }
}];

const ctx = $('Montar Contexto IA').first().json;
const raw = String($json.output || '').trim();

function sanitize(text) {
  return String(text || '')
    .replace(/[*_`#>]+/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

function splitLongSentence(sentence, maxLen = 260) {
  const parts = [];
  let remaining = sentence.trim();

  while (remaining.length > maxLen) {
    const slice = remaining.slice(0, maxLen + 1);
    let breakAt = Math.max(slice.lastIndexOf('. '), slice.lastIndexOf('! '), slice.lastIndexOf('? '));
    if (breakAt < 100) {
      breakAt = Math.max(slice.lastIndexOf('; '), slice.lastIndexOf(': '), slice.lastIndexOf(', '));
    }
    if (breakAt < 100) {
      breakAt = slice.lastIndexOf(' ');
    }
    if (breakAt < 60) {
      breakAt = maxLen;
    }

    parts.push(remaining.slice(0, breakAt + 1).trim());
    remaining = remaining.slice(breakAt + 1).trim();
  }

  if (remaining) {
    parts.push(remaining);
  }

  return parts;
}

function buildBlocks(text, maxLen = 260) {
  const cleaned = sanitize(text);
  if (!cleaned) {
    return [];
  }

  const sentences = cleaned.split(/(?<=[.!?])\s+/).filter(Boolean);
  const blocks = [];
  let current = '';

  for (const sentence of sentences) {
    if (sentence.length > maxLen) {
      const expanded = splitLongSentence(sentence, maxLen);
      for (const part of expanded) {
        if (!current) {
          current = part;
          continue;
        }
        if ((current + ' ' + part).length <= maxLen) {
          current += ' ' + part;
        } else {
          blocks.push(current.trim());
          current = part;
        }
      }
      continue;
    }

    if (!current) {
      current = sentence;
    } else if ((current + ' ' + sentence).length <= maxLen) {
      current += ' ' + sentence;
    } else {
      blocks.push(current.trim());
      current = sentence;
    }
  }

  if (current) {
    blocks.push(current.trim());
  }

  const normalizedBlocks = blocks.length > 0 ? blocks : [cleaned];
  if (normalizedBlocks.length <= 3) {
    return normalizedBlocks;
  }

  const limited = normalizedBlocks.slice(0, 2);
  limited.push(normalizedBlocks.slice(2).join(' '));
  return limited;
}

let aiReply = sanitize(raw);
const saudacaoNome = ctx.nameConflict ? '' : (ctx.preferredGreetingName || '');

if (aiReply === '') {
  if (ctx.hasMedia && !ctx.receivedText) {
    aiReply = `Recebi seu anexo na ${ctx.companyName}. Vou registrar aqui e seguir com o atendimento.`;
  } else if (ctx.clienteEncontrado && saudacaoNome) {
    aiReply = `Oi, ${saudacaoNome}. Vi sua mensagem agora. Como posso te ajudar por aqui?`;
  } else if (ctx.clienteEncontrado) {
    aiReply = `Oi. Vi sua mensagem agora e localizei seu cadastro na ${ctx.companyName}. Como posso te ajudar por aqui?`;
  } else {
    aiReply = `Oi. Recebi sua mensagem na ${ctx.companyName}, mas ainda nao localizei cadastro por este numero. Pode me informar seu nome completo para eu continuar o atendimento?`;
  }
}

const outputBlocks = buildBlocks(aiReply, 260);

return {
  ...ctx,
  aiRawResponse: $json,
  aiReply,
  outputBlocks
};
